var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City scene not loaded"); return; }
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobActiveHUD hud = null;
foreach (var r in roots) {
    hud = r.GetComponentInChildren<Sim.Jobs.JobActiveHUD>(true);
    if (hud != null) break;
}
if (hud == null) { Debug.LogError("JobActiveHUD not found"); return; }
var so = new UnityEditor.SerializedObject(hud);
so.Update();
var sortRoot = hud.GetComponentsInChildren<UnityEngine.Transform>(true);
UnityEngine.Transform sortProgressRoot = null;
TMPro.TMP_Text sortProgressText = null;
foreach (var t in sortRoot) {
    if (t.name == "Sort Progress") sortProgressRoot = t;
    if (t.name == "Sort Progress Text") sortProgressText = t.GetComponent<TMPro.TMP_Text>();
}
if (sortProgressRoot != null) so.FindProperty("sortProgressRoot").objectReferenceValue = sortProgressRoot.gameObject;
if (sortProgressText != null) so.FindProperty("sortProgressText").objectReferenceValue = sortProgressText;
so.ApplyModifiedProperties();
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
Debug.Log("[Wire] sortProgressRoot=" + (sortProgressRoot != null) + " sortProgressText=" + (sortProgressText != null));
